syntax = "proto3";
package shop.v1;

enum Status {
  UNKNOWN = 0;
  OPEN = 1;
  CLOSED = 2;
}

message Order {
  string order_id = 1;
  uint64 total_cents = 2;
  Status status = 3;
  string tags = 4;
  int32 discount_cents = 5;
}

before.example:
syntax = "proto3";
package shop.v1;

enum Status {
  STATUS_UNSPECIFIED = 0;
  OPEN = 1;
  CLOSED = 2;
}

message Order {
  string order_id = 1;
  int64 total_cents = 2;
  Status status = 3;
  repeated string tags = 4;
  string note = 5;
}
